/**
 * Crea iconos PNG desde data URLs base64
 * Estos son PNGs mínimos válidos que funcionan como placeholder
 */

const fs = require('fs');
const path = require('path');

// PNG 192x192 - Un cuadrado azul simple con transparencia
const icon192Base64 = ``;

// PNG 512x512 - Un cuadrado azul simple
const icon512Base64 = ``;

// Directorio de salida
const iconsDir = path.join(__dirname, '..', 'public', 'icons');

// Crear directorio si no existe
if (!fs.existsSync(iconsDir)) {
  fs.mkdirSync(iconsDir, { recursive: true });
  console.log('✓ Created icons directory');
}

// Convertir base64 a buffer y guardar
function saveIcon(base64Data, filename) {
  const buffer = Buffer.from(base64Data, 'base64');
  const filePath = path.join(iconsDir, filename);
  fs.writeFileSync(filePath, buffer);
  return filePath;
}

try {
  saveIcon(icon192Base64, 'icon-192.png');
  console.log('✓ Created icon-192.png');

  saveIcon(icon512Base64, 'icon-512.png');
  console.log('✓ Created icon-512.png');

  console.log('\n✓ PWA icons created successfully!');
  console.log('\n⚠️  These are minimal placeholder icons.');
  console.log('For production, create professional icons with:');
  console.log('  - Your brand logo');
  console.log('  - Proper colors and design');
  console.log('  - Tools like Figma, Photoshop, or https://realfavicongenerator.net/');
} catch (error) {
  console.error('✗ Error creating icons:', error);
  process.exit(1);
}
